    44  /* dump the page struct info */
    45  static void
    46  dump_page_info(Jbig2Ctx *ctx, Jbig2Segment *segment, Jbig2Page *page)
    47  {
    48      if (page->x_resolution == 0) {
    49          jbig2_error(ctx, JBIG2_SEVERITY_INFO, segment->number, "page %d image is %dx%d (unknown res)", page->number, page->width, page->height);
    50      } else if (page->x_resolution == page->y_resolution) {
    51          jbig2_error(ctx, JBIG2_SEVERITY_INFO, segment->number, "page %d image is %dx%d (%d ppm)", page->number, page->width, page->height, page->x_resolution);
    52      } else {
    53          jbig2_error(ctx, JBIG2_SEVERITY_INFO, segment->number,
    54                      "page %d image is %dx%d (%dx%d ppm)", page->number, page->width, page->height, page->x_resolution, page->y_resolution);
    55      }
    56      if (page->striped) {
    57          jbig2_error(ctx, JBIG2_SEVERITY_INFO, segment->number, "\tmaximum stripe size: %d", page->stripe_size);
    58      }
    59  }
