    61  /**
    62   * jbig2_page_info: parse page info segment
    63   *
    64   * Parse the page info segment data and fill out a corresponding
    65   * Jbig2Page struct and ready it for subsequent rendered data,
    66   * including allocating an image buffer for the page (or the first stripe)
    67   **/
    68  int
    69  jbig2_page_info(Jbig2Ctx *ctx, Jbig2Segment *segment, const uint8_t *segment_data)
    70  {
    71      Jbig2Page *page, *pages;
    72
    73      /* a new page info segment implies the previous page is finished */
    74      page = &(ctx->pages[ctx->current_page]);
    75      if (page->number != 0 && (page->state == JBIG2_PAGE_NEW || page->state == JBIG2_PAGE_FREE)) {
    76          page->state = JBIG2_PAGE_COMPLETE;
    77          jbig2_error(ctx, JBIG2_SEVERITY_WARNING, segment->number, "unexpected page info segment, marking previous page finished");
    78      }
    79
    80      /* find a free page */
    81      {
    82          int index, j;
    83
    84          index = ctx->current_page;
    85          while (ctx->pages[index].state != JBIG2_PAGE_FREE) {
    86              index++;
    87              if (index >= ctx->max_page_index) {
    88                  /* grow the list */
    89                  pages = jbig2_renew(ctx, ctx->pages, Jbig2Page, (ctx->max_page_index <<= 2));
    90                  if (pages == NULL) {
    91                      return jbig2_error(ctx, JBIG2_SEVERITY_FATAL, segment->number, "failed to reallocate pages");
    92                  }
    93                  ctx->pages = pages;
    94                  for (j = index; j < ctx->max_page_index; j++) {
    95                      ctx->pages[j].state = JBIG2_PAGE_FREE;
    96                      ctx->pages[j].number = 0;
    97                      ctx->pages[j].image = NULL;
    98                  }
    99              }
   100          }
   101          page = &(ctx->pages[index]);
   102          ctx->current_page = index;
   103          page->state = JBIG2_PAGE_NEW;
   104          page->number = segment->page_association;
   105      }
   106
   107      /* FIXME: would be nice if we tried to work around this */
   108      if (segment->data_length < 19) {
   109          return jbig2_error(ctx, JBIG2_SEVERITY_FATAL, segment->number, "segment too short");
   110      }
   111
   112      /* 7.4.8.x */
   113      page->width = jbig2_get_uint32(segment_data);
   114      page->height = jbig2_get_uint32(segment_data + 4);
   115
   116      page->x_resolution = jbig2_get_uint32(segment_data + 8);
   117      page->y_resolution = jbig2_get_uint32(segment_data + 12);
   118      page->flags = segment_data[16];
   119      /* Check for T.88 amendment 3 */
   120      if (page->flags & 0x80)
   121          return jbig2_error(ctx, JBIG2_SEVERITY_FATAL, segment->number, "page segment indicates use of color segments (NYI)");
   122
   123      /* 7.4.8.6 */
   124      {
   125          int16_t striping = jbig2_get_int16(segment_data + 17);
   126
   127          if (striping & 0x8000) {
   128              page->striped = TRUE;
   129              page->stripe_size = striping & 0x7FFF;
   130          } else {
   131              page->striped = FALSE;
   132              page->stripe_size = 0;      /* would page->height be better? */
   133          }
   134      }
   135      if (page->height == 0xFFFFFFFF && page->striped == FALSE) {
   136          jbig2_error(ctx, JBIG2_SEVERITY_WARNING, segment->number, "height is unspecified but page is not marked as striped, assuming striped with maximum strip size");
   137          page->striped = TRUE;
   138          page->stripe_size = 0x7FFF;
   139      }
   140      page->end_row = 0;
   141
   142      if (segment->data_length > 19) {
   143          jbig2_error(ctx, JBIG2_SEVERITY_WARNING, segment->number, "extra data in segment");
   144      }
   145
   146      dump_page_info(ctx, segment, page);
   147
   148      /* allocate an appropriate page image buffer */
   149      /* 7.4.8.2 */
   150      if (page->height == 0xFFFFFFFF) {
   151          page->image = jbig2_image_new(ctx, page->width, page->stripe_size);
   152      } else {
   153          page->image = jbig2_image_new(ctx, page->width, page->height);
   154      }
   155      if (page->image == NULL) {
   156          return jbig2_error(ctx, JBIG2_SEVERITY_WARNING, segment->number, "failed to allocate buffer for page image");
   157      } else {
   158          /* 8.2 (3) fill the page with the default pixel value */
   159          jbig2_image_clear(ctx, page->image, (page->flags & 4));
   160          jbig2_error(ctx, JBIG2_SEVERITY_DEBUG, segment->number,
   161                      "allocated %dx%d page image (%d bytes)", page->image->width, page->image->height, page->image->stride * page->image->height);
   162      }
   163
   164      return 0;
   165  }
