   167  /**
   168   * jbig2_end_of_stripe: parse and implement an end of stripe segment
   169   **/
   170  int
   171  jbig2_end_of_stripe(Jbig2Ctx *ctx, Jbig2Segment *segment, const uint8_t *segment_data)
   172  {
   173      Jbig2Page *page = &ctx->pages[ctx->current_page];
   174      uint32_t end_row;
   175
   176      if (segment->data_length < 4)
   177          return jbig2_error(ctx, JBIG2_SEVERITY_FATAL, segment->number, "segment too short");
   178      end_row = jbig2_get_uint32(segment_data);
   179      if (end_row < page->end_row) {
   180          jbig2_error(ctx, JBIG2_SEVERITY_WARNING, segment->number,
   181                      "end of stripe segment with non-positive end row advance (new end row %d vs current end row %d)", end_row, page->end_row);
   182      } else {
   183          jbig2_error(ctx, JBIG2_SEVERITY_INFO, segment->number, "end of stripe: advancing end row from %u to %u", page->end_row, end_row);
   184      }
   185
   186      page->end_row = end_row;
   187
   188      return 0;
   189  }
