   191  /**
   192   * jbig2_complete_page: complete a page image
   193   *
   194   * called upon seeing an 'end of page' segment, this routine
   195   * marks a page as completed so it can be returned.
   196   * compositing will have already happened in the previous
   197   * segment handlers.
   198   **/
   199  int
   200  jbig2_complete_page(Jbig2Ctx *ctx)
   201  {
   202      int code;
   203
   204      /* check for unfinished segments */
   205      if (ctx->segment_index != ctx->n_segments) {
   206          Jbig2Segment *segment = ctx->segments[ctx->segment_index];
   207
   208          /* Some versions of Xerox Workcentre generate PDF files
   209             with the segment data length field of the last segment
   210             set to -1. Try to cope with this here. */
   211          if ((segment->data_length & 0xffffffff) == 0xffffffff) {
   212              jbig2_error(ctx, JBIG2_SEVERITY_WARNING, segment->number, "file has an invalid segment data length; trying to decode using the available data");
